'use strict';
const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=[],headers=[],mapping={},pending=[],filename='',demo=true,locale='en',queryRows=[],workbook=null;
const roles={date:'Ngày',app:'Sản phẩm / phân khúc',downloads:'Downloads',revenue:'Revenue',dau:'DAU',spend:'UA spend',retention_d1:'Retention D1',retention_d7:'Retention D7',retention_d30:'Retention D30',user_id:'User ID',event_name:'Event name',event_date:'Event date',number:'Số khác',category:'Phân loại',ignore:'Bỏ qua'};
const aliases={date:['date','month','week','day','ngay'],app:['app','appname','application','product','gamename','title','category'],downloads:['downloads','download','installs','units','estimateddownloads'],revenue:['revenue','estimatedrevenue','iaprevenue','sales','doanhthu'],dau:['dau','dailyactiveusers','activeusers'],spend:['spend','cost','adspend','uaspend'],retention_d1:['d1','retentiond1','d1retention'],retention_d7:['d7','retentiond7','d7retention'],retention_d30:['d30','retentiond30','d30retention'],user_id:['userid','userpseudoid','playerid'],event_name:['eventname','event'],event_date:['eventdate','eventtimestamp']};
function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function num(v){if(typeof v==='number')return Number.isFinite(v)?v:null;if(v==null||String(v).trim()==='')return null;let s=String(v).trim().replace(/[$€₫%\s]/g,'');if(locale==='vi')s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'');if(!/^-?\d*(\.\d+)?$/.test(s)||s==='')return null;return Number(s)}
function day(v){if(v==null||v==='')return null;if(v instanceof Date)return Number.isFinite(+v)?v.toISOString().slice(0,10):null;let s=String(v).trim();if(/^\d{8}$/.test(s))s=s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6);if(/^\d{4}-\d{2}$/.test(s))s+='-01';if(/^\d{2}[/.]\d{2}[/.]\d{4}$/.test(s)){const a=s.split(/[/.]/);s=a[2]+'-'+a[1]+'-'+a[0]}const m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;const d=new Date(m[0]+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===m[0]?m[0]:null}
function csvParse(text){text=text.replace(/^\uFEFF/,'');const line=text.split(/\r?\n/)[0];let delim=['\t',';',','].sort((a,b)=>line.split(b).length-line.split(a).length)[0];let out=[],r=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===delim&&!quoted){r.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;r.push(field);if(r.some(v=>v.trim()))out.push(r);r=[];field=''}else field+=c}if(quoted)throw Error('CSV có dấu ngoặc kép chưa đóng.');r.push(field);if(r.some(v=>v.trim()))out.push(r);if(out.length<2)throw Error('File cần header và ít nhất một dòng dữ liệu.');const h=out.shift().map(v=>v.trim());if(h.some(v=>!v)||new Set(h).size!==h.length)throw Error('Header trống hoặc trùng tên. Vui lòng sửa file.');if(out.some(r=>r.length!==h.length))throw Error('Số cột không đồng nhất; kiểm tra delimiter và dòng tiêu đề.');return out.map(r=>Object.fromEntries(h.map((v,i)=>[v,r[i]])))}
function infer(h,data){let k=normalize(h);for(const [role,a]of Object.entries(aliases))if(a.includes(k))return role;if(data.slice(0,100).filter(r=>num(r[h])!==null).length>data.slice(0,100).length*.8)return 'number';return 'category'}
function notify(s){$('notice').textContent=s}
function tab(name){document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name))}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
function fmt(n){return n==null?'—':new Intl.NumberFormat('en',{maximumFractionDigits:2,notation:Math.abs(n)>10000?'compact':'standard'}).format(n)}
function table(data,max=100){if(!data.length)return '<p class="muted">Chưa có dữ liệu.</p>';const h=Object.keys(data[0]);return '<table><thead><tr>'+h.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+data.slice(0,max).map(r=>'<tr>'+h.map(x=>'<td>'+esc(r[x])+'</td>').join('')+'</tr>').join('')+'</tbody></table>'+(data.length>max?'<p class="muted">Hiển thị '+max+' / '+data.length+' dòng.</p>':'')}
function begin(data,name,isDemo=false){if(!Array.isArray(data)||!data.length||data.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('Cần mảng các object với tên cột.');if(data.length>100000)throw Error('MVP hỗ trợ tối đa 100.000 dòng.');pending=data;filename=name;demo=isDemo;headers=[...new Set(data.flatMap(Object.keys))];if(headers.length>100)throw Error('MVP hỗ trợ tối đa 100 cột.');mapping=Object.fromEntries(headers.map(h=>[h,infer(h,data)]));renderMapping();tab('import')}
function renderMapping(){const el=$('mapping');el.hidden=false;el.innerHTML='<div class="cardhead"><h2>Kiểm tra cấu trúc · '+esc(filename)+'</h2><span class="tag">'+pending.length+' ROWS</span></div><div class="toolbar">'+(workbook?'<label>Sheet <select id="sheet">'+workbook.SheetNames.map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label>':'')+'<label>Định dạng số <select id="locale"><option value="en">Quốc tế: 1,234.56</option><option value="vi">Việt Nam: 1.234,56</option></select></label></div>'+headers.map((h,i)=>'<div class="maprow"><b>'+esc(h)+'</b><span class="muted">'+esc(pending[0][h])+'</span><select data-map="'+i+'" aria-label="Mapping '+esc(h)+'">'+Object.entries(roles).map(([r,n])=>'<option value="'+r+'" '+(mapping[h]===r?'selected':'')+'>'+n+'</option>').join('')+'</select></div>').join('')+'<p class="muted">Ngày: YYYY-MM-DD, YYYYMMDD, DD/MM/YYYY; tháng: YYYY-MM. Revenue và spend giữ đơn vị tiền tệ của file. Không tự quy đổi.</p><button id="apply" class="primary">Tạo dashboard →</button>';$('locale').value=locale;$('locale').onchange=e=>locale=e.target.value;el.querySelectorAll('[data-map]').forEach(e=>e.onchange=()=>mapping[headers[+e.dataset.map]]=e.value);$('apply').onclick=apply;if(workbook){$('sheet').value=workbook.current||workbook.SheetNames[0];$('sheet').onchange=e=>{workbook.current=e.target.value;begin(XLSX.utils.sheet_to_json(workbook.Sheets[e.target.value],{defval:'',raw:true}),filename)}}}
function apply(){const assigned=Object.values(mapping).filter(v=>!['number','category','ignore'].includes(v));if(new Set(assigned).size!==assigned.length){notify('Mỗi vai trò chính chỉ được map một cột.');return}rows=pending;const metrics=headers.filter(h=>!['date','app','user_id','event_name','event_date','category','ignore'].includes(mapping[h]));$('metric').innerHTML=metrics.map(h=>'<option>'+esc(h)+'</option>').join('');const app=col('app');$('dimensionFilter').innerHTML='<option value="">Tất cả phân khúc</option>'+(app?[...new Set(rows.map(r=>r[app]))].sort().map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join(''):'');render();tab(col('user_id')&&col('event_name')?'product':'overview');notify((demo?'Đang dùng dữ liệu minh họa. ':'')+'Đã nhận '+rows.length+' dòng. Mapping đã được áp dụng.');$('retention').innerHTML='';}
const col=r=>headers.find(h=>mapping[h]===r);
function filtered(){const a=col('app'),v=$('dimensionFilter').value;return rows.filter(r=>!v||String(r[a])===v)}
function aggregate(values,rate){const v=values.filter(v=>v!==null);return v.length?(rate?v.reduce((a,b)=>a+b,0)/v.length:v.reduce((a,b)=>a+b,0)):null}
function series(data,metric){const d=col('date')||col('event_date');const g=new Map();if(!d)return [];for(const r of data){const date=day(r[d]),n=num(r[metric]);if(!date||n===null)continue;if(!g.has(date))g.set(date,[]);g.get(date).push(n)}const rate=/retention|dau/.test(mapping[metric]);return [...g].sort((a,b)=>a[0].localeCompare(b[0])).map(([x,v])=>({x,y:aggregate(v,rate)}))}
function lineChart(s){if(!s.length)return '<p class="muted">Cần cột ngày và chỉ số dạng số để tạo biểu đồ.</p>';const w=700,h=230,left=58,right=20,top=15,bottom=42;let lo=Math.min(0,...s.map(v=>v.y)),hi=Math.max(0,...s.map(v=>v.y));if(lo===hi)hi=lo+1;const xp=i=>left+i/Math.max(1,s.length-1)*(w-left-right),yp=y=>top+(hi-y)/(hi-lo)*(h-top-bottom);let grid='';for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4,y=yp(v);grid+='<line x1="'+left+'" y1="'+y+'" x2="680" y2="'+y+'" stroke="#edf0f2"/><text x="2" y="'+(y+4)+'">'+fmt(v)+'</text>'}const points=s.map((v,i)=>xp(i)+','+yp(v.y)).join(' ');return '<svg viewBox="0 0 700 230" role="img" aria-label="Biểu đồ xu hướng">'+grid+'<polygon points="'+left+','+yp(lo)+' '+points+' '+xp(s.length-1)+','+yp(lo)+'" fill="#eaf6f1"/><polyline points="'+points+'" fill="none" stroke="#209880" stroke-width="3"/>'+s.map((v,i)=>'<circle cx="'+xp(i)+'" cy="'+yp(v.y)+'" r="3" fill="#209880"><title>'+esc(v.x)+': '+fmt(v.y)+'</title></circle>').join('')+[...new Set([0,Math.floor((s.length-1)/2),s.length-1])].map(i=>'<text x="'+xp(i)+'" y="218" text-anchor="'+(i===0?'start':i===s.length-1?'end':'middle')+'">'+esc(s[i].x)+'</text>').join('')+'</svg>'}
function render(){const data=filtered(),m=$('metric').value,rate=/retention|dau/.test(mapping[m]||''),s=series(data,m),total=aggregate(data.map(r=>num(r[m])),rate);const a=col('app');let groups=[];if(a){const g=new Map();data.forEach(r=>{const key=String(r[a]??'Không rõ');if(!g.has(key))g.set(key,[]);g.get(key).push(num(r[m]))});groups=[...g].map(([name,v])=>({name,value:aggregate(v,rate)})).filter(x=>x.value!==null).sort((a,b)=>b.value-a.value)}const n=s.length,change=n>1&&s[n-2].y!==0?(s[n-1].y/s[n-2].y-1)*100:null;const invalid=data.filter(r=>r[m]!=null&&r[m]!==''&&num(r[m])===null).length;const mode=rate?'Trung bình đơn giản':'Tổng trong file';$('source').textContent=(demo?'● DEMO · ':'● FILE · ')+filename;$('kpis').innerHTML=[['Chỉ số đang xem',fmt(total),m?m+' · '+mode:'Chưa map chỉ số'],['Thay đổi kỳ cuối',change==null?'—':(change>=0?'+':'')+fmt(change)+'%',n>1?s[n-2].x+' → '+s[n-1].x:'Cần ít nhất 2 kỳ'],['Sản phẩm / phân khúc',a?fmt(new Set(data.map(r=>r[a])).size):'—','Theo phạm vi lọc'],['Chất lượng dữ liệu',fmt(data.length),invalid+' dòng số không hợp lệ']].map(([l,v,c])=>'<div class="kpi"><small>'+esc(l)+'</small><strong>'+esc(v)+'</strong><div class="change">'+esc(c)+'</div></div>').join('');$('chartSub').textContent=(m||'Chưa có metric')+' · '+mode+' theo từng ngày/tháng';$('chart').innerHTML=lineChart(s);const insight=[];if(n>1)insight.push(['Biến động gần nhất',change==null?'Kỳ trước bằng 0, không tính tăng trưởng %.':m+' '+(change>=0?'tăng ':'giảm ')+fmt(Math.abs(change))+'% so với kỳ liền trước. Kiểm tra độ đầy đủ của kỳ cuối trước khi kết luận.']);else insight.push(['Cần thêm chuỗi thời gian','Nhập ít nhất hai kỳ để đánh giá sự thay đổi.']);if(groups.length)insight.push(['Dẫn đầu trong file',groups[0].name+' đạt '+fmt(groups[0].value)+' '+m+'. So sánh thêm theo quốc gia và platform trước khi chọn cơ hội.']);insight.push(['Bước kiểm chứng tiếp theo',mapping[m]==='revenue'?'Đối chiếu tăng trưởng revenue với downloads, monetization và thay đổi giá.':mapping[m]==='downloads'?'Đối chiếu downloads với revenue và retention để phân biệt quy mô với chất lượng.':'Phân đoạn theo phiên bản, nguồn acquisition và cohort để tìm nguyên nhân.']);insight.push(['Giới hạn kết luận','Phân tích theo quy tắc, chỉ phản ánh file nhập; không suy rộng thành toàn thị trường hoặc dự báo. '+(rate?'DAU / retention là trung bình đơn giản, thiếu trọng số.':'Không gộp các dòng từ nhiều nguồn.')]);$('insights').innerHTML=insight.map(([h,p])=>'<div class="insight"><b>'+esc(h)+'</b><p>'+esc(p)+'</p></div>').join('');const max=Math.max(1,...groups.map(g=>Math.abs(g.value)));$('ranking').innerHTML=groups.length?groups.slice(0,8).map((g,i)=>'<div class="barrow"><span>'+String(i+1).padStart(2,'0')+' &nbsp; '+esc(g.name)+'</span><div class="track"><div class="fill" style="width:'+Math.abs(g.value)/max*100+'%"></div></div><b>'+fmt(g.value)+'</b></div>').join(''):'<p class="muted">Map cột sản phẩm để so sánh.</p>';$('table').innerHTML=table(data);$('rowsLabel').textContent=data.length+' dòng';$('productSummary').innerHTML='<h2>Chỉ số sản phẩm trong file</h2>'+Object.keys(roles).filter(k=>/revenue|downloads|dau|spend|retention/.test(k)&&col(k)).map(k=>'<p><b>'+roles[k]+'</b> · '+fmt(aggregate(data.map(r=>num(r[col(k)])),/retention|dau/.test(k)))+' <span class="muted">'+(/retention|dau/.test(k)?'trung bình đơn giản, đơn vị theo file':'tổng trong phạm vi lọc')+'</span></p>').join('')+'<p class="muted">Không tự suy ra LTV, ROAS hay churn nếu thiếu cohort, spend hoặc mẫu số tương ứng.</p>';}
$('metric').onchange=render;$('dimensionFilter').onchange=render;
function marketDemo(){workbook=null;locale='en';let d=[];const apps=['Puzzle Garden','Merge Stories','Idle Kingdom','FitHabit','Focus Flow'];for(let i=0;i<6;i++)apps.forEach((app,j)=>d.push({Month:'2026-'+String(i+4).padStart(2,'0'),App:app,Downloads:Math.round((85000-j*12000)*(1+i*(.12-j*.03))),Revenue:Math.round((45000+j*8000)*(1+i*(.16-j*.025))),DAU:Math.round(18000*(1+i*.08)/(j+1)),D1:Math.round(39-j*2+i*.5),D7:Math.round(17-j+i*.4),Spend:Math.round(22000*(1+i*.06)/(j+1))}));begin(d,'Mobile portfolio · Apr–Sep 2026',true);apply()}
$('demo').onclick=marketDemo;
async function loadFile(f){try{if(!f)return;if(f.size>20*1024*1024)throw Error('File vượt giới hạn 20 MB.');workbook=null;let data;if(/\.xlsx?$/.test(f.name)){if(!window.XLSX)throw Error('Thư viện Excel chưa có. Hãy dùng CSV.');workbook=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true});data=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{defval:'',raw:true})}else if(/\.json$/i.test(f.name))data=JSON.parse(await f.text());else data=csvParse(await f.text());begin(data,f.name);notify('Đã đọc file. Kiểm tra mapping trước khi phân tích.')}catch(e){notify(e.message)}$('file').value=''}
$('file').onchange=e=>loadFile(e.target.files[0]);$('drop').ondragover=e=>e.preventDefault();$('drop').ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0])};
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('sample').onclick=()=>download('market-sample.csv','Month,App,Downloads,Revenue,DAU,D1,D7,Spend\n2026-08,Puzzle Garden,120000,80000,24000,40,18,30000\n2026-09,Puzzle Garden,145000,95000,28000,42,20,35000\n2026-08,Merge Stories,100000,72000,19000,37,15,25000\n2026-09,Merge Stories,110000,76000,21000,38,16,27000','text/csv');
$('export').onclick=()=>download('po-pulse-analysis.md','# PO Pulse\n\nSource: '+filename+(demo?' (DEMO)':'')+'\nRows: '+filtered().length+'\nMetric: '+$('metric').value+'\n\n'+$('insights').innerText+'\n\nMapping: '+JSON.stringify(mapping,null,2));
function retentionCalc(data,map,event,cohort){const u=Object.keys(map).find(h=>map[h]==='user_id'),e=Object.keys(map).find(h=>map[h]==='event_name'),t=Object.keys(map).find(h=>map[h]==='event_date')||Object.keys(map).find(h=>map[h]==='date');if(!u||!e||!t)throw Error('Cần mapping user_id, event_name, event_date.');let valid=[],bad=0;for(const r of data){const d=day(r[t]);if(!d||r[u]==null||r[u]===''){bad++;continue}valid.push({u:String(r[u]),e:String(r[e]),d})}if(!valid.length)throw Error('Không có event với ngày hợp lệ.');const end=valid.reduce((m,r)=>r.d>m?r.d:m,'');const users=new Map();valid.forEach(r=>{if(r.e===cohort&&(!users.has(r.u)||r.d<users.get(r.u).start))users.set(r.u,{start:r.d,days:new Set(),exposed:false})});valid.forEach(r=>{const v=users.get(r.u);if(v&&r.d>=v.start){v.days.add(r.d);if(r.e===event&&r.d===v.start)v.exposed=true}});if(!users.size)throw Error('Không tìm thấy event tạo cohort: '+cohort);let results=[];for(const exposed of [true,false])for(const dn of [1,3,7,14,30]){const eligible=[...users.values()].filter(v=>v.exposed===exposed&&new Date(v.start+'T00:00:00Z').getTime()+dn*864e5<=new Date(end+'T00:00:00Z').getTime());const retained=eligible.filter(v=>v.days.has(new Date(new Date(v.start+'T00:00:00Z').getTime()+dn*864e5).toISOString().slice(0,10))).length;results.push({group:exposed?'Có '+event+' ở D0':'Không có '+event+' ở D0',day:dn,eligible:eligible.length,retained,retention:eligible.length?retained/eligible.length*100:null})}return {results,end,bad,users:users.size}}
$('calcRetention').onclick=()=>{try{const event=$('eventName').value.trim(),cohort=$('cohortEvent').value.trim();if(!event||!cohort||event===cohort)throw Error('Nhập hai event khác nhau để tạo nhóm có/không.');const r=retentionCalc(rows,mapping,event,cohort);$('retention').innerHTML='<p>'+r.users+' user cohort · Quan sát đến '+r.end+' · Bỏ qua '+r.bad+' dòng lỗi</p>'+table(r.results.map(v=>({Nhóm:v.group,Ngày:'D'+v.day,'Đủ thời gian':v.eligible,'Quay lại':v.retained,'Retention %':v.retention==null?'—':v.retention.toFixed(2)})))+'<p class="muted">Active = phát sinh bất kỳ event nào ở Dn. Dùng định nghĩa active khác cần chỉnh SQL.</p>'}catch(e){notify(e.message)}};
$('eventDemo').onclick=()=>{workbook=null;locale='en';let d=[];for(let i=0;i<120;i++){let start=new Date(Date.UTC(2026,8,1+i%10)),uid='u'+i;d.push({user_id:uid,event_name:'first_open',event_date:start.toISOString().slice(0,10)});if(i%2===0)d.push({user_id:uid,event_name:'tutorial_complete',event_date:start.toISOString().slice(0,10)});for(let dn=1;dn<=30;dn++)if((i*13+dn*7)%100<(i%2===0?65:40)*Math.exp(-dn/18))d.push({user_id:uid,event_name:'session_start',event_date:new Date(+start+dn*864e5).toISOString().slice(0,10)})}d.push({user_id:'end-marker',event_name:'session_start',event_date:'2026-10-10'});begin(d,'Event log mẫu · Sep 2026',true);apply();$('calcRetention').click()};
function buildSQL(tbl,event,from,until){if(!/^[\w-]+\.\w+\.\w+$/.test(tbl))throw Error('Nhập bảng project.dataset.table với ký tự hợp lệ.');if(!event||event.length>100)throw Error('Nhập event phân nhóm.');if(!day(from)||!day(until)||from>until)throw Error('Khoảng thời gian chưa hợp lệ.');const lit=event.replace(/\\/g,'\\\\').replace(/'/g,"\\'");return `-- Schema chuẩn hóa: user_id STRING, event_name STRING, event_date DATE
-- Cohort = first_open đầu tiên trong lịch sử; exposure chỉ trong D0.
-- Ngày cuối quan sát phải là ngày dataset đã ingest đầy đủ.
WITH first_seen AS (
  SELECT user_id, MIN(event_date) AS cohort_date
  FROM \`${tbl}\`
  WHERE event_name = 'first_open' AND user_id IS NOT NULL
    AND event_date <= DATE '${until}'
  GROUP BY 1
), cohort AS (
  SELECT * FROM first_seen
  WHERE cohort_date BETWEEN DATE '${from}' AND DATE '${until}'
), activity AS (
  SELECT DISTINCT user_id, event_date, event_name
  FROM \`${tbl}\`
  WHERE event_date BETWEEN DATE '${from}' AND DATE '${until}'
), segments AS (
  SELECT c.user_id, c.cohort_date,
    IF(COUNTIF(a.event_name = '${lit}' AND a.event_date = c.cohort_date) > 0,
       'event_D0', 'no_event_D0') AS segment
  FROM cohort c LEFT JOIN activity a USING(user_id)
  GROUP BY 1, 2
), user_days AS (
  SELECT DISTINCT user_id, event_date FROM activity
)
SELECT s.segment, dn AS day,
  COUNT(*) AS eligible_users,
  COUNTIF(a.user_id IS NOT NULL) AS retained_users,
  ROUND(100 * SAFE_DIVIDE(COUNTIF(a.user_id IS NOT NULL), COUNT(*)), 2) AS retention_pct
FROM segments s CROSS JOIN UNNEST([1,3,7,14,30]) AS dn
LEFT JOIN user_days a ON a.user_id = s.user_id
  AND a.event_date = DATE_ADD(s.cohort_date, INTERVAL dn DAY)
WHERE DATE_ADD(s.cohort_date, INTERVAL dn DAY) <= DATE '${until}'
GROUP BY 1, 2 ORDER BY 1, 2`}
$('generateSQL').onclick=()=>{try{$('sql').value=buildSQL($('eventTable').value.trim(),$('sqlEvent').value.trim(),$('from').value,$('until').value);notify('Đã tạo SQL. Kiểm tra schema và khoảng thời gian trước khi chạy.')}catch(e){notify(e.message)}};
$('copySQL').onclick=async()=>{try{await navigator.clipboard.writeText($('sql').value);notify('Đã sao chép SQL.')}catch{download('retention.sql',$('sql').value)}};
async function bqRequest(path,method,body){const response=await fetch('https://bigquery.googleapis.com/bigquery/v2/'+path,{method,headers:{Authorization:'Bearer '+$('token').value.trim(),'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const j=await response.json();if(!response.ok)throw Error(j.error?.message||'BigQuery HTTP '+response.status);if(j.errors?.length)throw Error(j.errors.map(e=>e.message).join('; '));return j}
async function query(dry){$('dryRun').disabled=$('runQuery').disabled=true;queryRows=[];$('useResult').hidden=true;$('queryResult').innerHTML='';$('queryChart').innerHTML='';try{const project=$('projectId').value.trim(),location=$('location').value.trim(),sql=$('sql').value.trim(),max=$('maxBytes').value.trim();if(!/^[a-z][a-z0-9-]{4,62}$/.test(project)||!$('token').value.trim())throw Error('Nhập project ID và access token.');if(!/^\d+$/.test(max)||BigInt(max)<=0n)throw Error('Giới hạn bytes phải là số nguyên dương.');const clean=sql.replace(/--[^\n]*/g,'').replace(/\/\*[\s\S]*?\*\//g,'').trim().replace(/;\s*$/,'');if(!/^(SELECT|WITH)\b/i.test(clean)||clean.includes(';'))throw Error('MVP chỉ cho phép SELECT/WITH một statement.');$('queryStatus').textContent=dry?'Đang ước tính…':'Đang chạy query…';const base='projects/'+encodeURIComponent(project);let result=await bqRequest(base+'/queries','POST',{query:sql,useLegacySql:false,dryRun:dry,location,maximumBytesBilled:max,maxResults:10000,timeoutMs:10000});if(dry){$('queryStatus').textContent='Ước tính: '+fmt(Number(result.totalBytesProcessed||0)/1e6)+' MB được xử lý. Chưa chạy query.';return}const ref=result.jobReference;const path=base+'/queries/'+encodeURIComponent(ref.jobId);let attempts=0;while(!result.jobComplete){if(++attempts>60)throw Error('Job vẫn chạy. Kiểm tra BigQuery console: '+ref.jobId);await new Promise(r=>setTimeout(r,1000));result=await bqRequest(path+'?location='+encodeURIComponent(ref.location||location)+'&timeoutMs=1000&maxResults=10000','GET')}const fields=result.schema?.fields||[];if(fields.some(f=>f.mode==='REPEATED'||f.type==='RECORD'))throw Error('Kết quả có nested/repeated fields. Hãy flatten trong SQL. Job đã hoàn thành.');let all=result.rows||[];const total=Number(result.totalRows||all.length);while(result.pageToken&&all.length<50000){result=await bqRequest(path+'?location='+encodeURIComponent(ref.location||location)+'&maxResults='+Math.min(10000,50000-all.length)+'&pageToken='+encodeURIComponent(result.pageToken),'GET');all.push(...(result.rows||[]))}queryRows=all.slice(0,50000).map(r=>Object.fromEntries(fields.map((f,i)=>[f.name,r.f[i]?.v??null])));$('queryStatus').textContent='Hoàn thành · '+queryRows.length+' / '+total+' dòng'+(total>queryRows.length?' · KẾT QUẢ BỊ GIỚI HẠN: hãy thu hẹp SQL.':'')+' · Job '+ref.jobId;$('queryResult').innerHTML=table(queryRows);$('useResult').hidden=!queryRows.length;if(fields.some(f=>f.name==='retention_pct')){$('queryChart').innerHTML=queryRows.slice(0,30).map(r=>'<div class="barrow"><span>'+esc(r.segment)+' D'+esc(r.day)+'</span><div class="track"><div class="fill" style="width:'+Math.max(0,Math.min(100,Number(r.retention_pct)||0))+'%"></div></div><b>'+fmt(Number(r.retention_pct))+'%</b></div>').join('')}}catch(e){$('queryStatus').textContent='Lỗi: '+e.message}finally{$('dryRun').disabled=$('runQuery').disabled=false}}
$('dryRun').onclick=()=>query(true);$('runQuery').onclick=()=>query(false);$('useResult').onclick=()=>{try{workbook=null;begin(queryRows,'BigQuery result')}catch(e){notify(e.message)}};
marketDemo();
if(typeof module!=='undefined')module.exports={csvParse,num,day,retentionCalc,buildSQL};
